const DAYS = ['일','월','화','수','목','금','토'];
const PRESETS = [['기본',[1,3,7,14,30]],['촘촘하게',[1,2,4,7,15,30]],['시험 직전',[1,2,3,5,7]],['장기 암기',[1,3,7,21,60,120]]];
const MODES = [['망각곡선대로',{sameDay:true,nextDay:true,eve:false,curve:true}],['수업 리듬',{sameDay:true,nextDay:false,eve:true,curve:false}],['전날만',{sameDay:false,nextDay:false,eve:true,curve:false}]];
const MODE_LABELS = {sameDay:'수업 당일',nextDay:'다음 날',eve:'다음 수업 전날',curve:'망각곡선 간격'};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
