const monthOf = value => value.slice(0,7)+'-01';
const itemName = item => item.subject || '과목 없음';
const SAFE_ERRORS = {stale_revision:'다른 기기에서 기록이 바뀌었어요. 최신 내용을 확인하고 다시 눌러 주세요.',undo_unavailable:'되돌릴 수 있는 8초가 지났거나 기록이 바뀌었어요.',invalid_input:'입력한 값과 글자 수를 확인해 주세요.',date_out_of_range:'날짜는 2000년부터 2100년 사이로 입력해 주세요.',routine_not_available:'이 루틴의 실행일과 오늘 또는 지난 날짜만 체크할 수 있어요.',recognition_disabled:'시간표 인식이 설정되지 않았어요. 아래에서 직접 입력해 주세요.',daily_limit:'오늘의 시간표 인식 횟수를 모두 사용했어요. 직접 입력하거나 내일 다시 시도해 주세요.'};
