export function validReminderState(value) {
  if (!value || !Number.isSafeInteger(value.revision) || value.revision < 0 || !date(value.today)
    || !Array.isArray(value.items) || value.items.length>5000 || !Array.isArray(value.routines) || value.routines.length>500
    || !Array.isArray(value.exams) || value.exams.length>1000 || !value.settings
    || !schedule.validOffsets(value.settings.offsets) || !['due','subject'].includes(value.settings.sort)
    || (value.settings.sem_start!==null && !date(value.settings.sem_start))
    || !value.holidays || Array.isArray(value.holidays) || typeof value.holidays!=='object') return false;
  if (!Object.entries(value.holidays).every(([key,name])=>date(key)&&text(name,100))) return false;
  if (value.source_keys!==undefined && (!Array.isArray(value.source_keys)||value.source_keys.length>100000||!value.source_keys.every(key=>text(key,120)))) return false;
  if (!value.items.every(item=>UUID.test(item.id) && text(item.title,200) && text(item.subject,40) && text(item.memo,200)
    && date(item.learned) && date(item.base) && schedule.validOffsets(item.offsets) && Array.isArray(item.reviews)
    && item.reviews.length<=12 && item.reviews.every(date) && (!item.skipped || date(item.skipped))
    && (!item.moved || (Number.isSafeInteger(item.moved.stage)&&date(item.moved.date))))) return false;
  if (!value.routines.every(row=>UUID.test(row.id)&&text(row.name,60)&&text(row.tag,40)&&date(row.start)
    && (!row.end||date(row.end)) && Array.isArray(row.days)&&row.days.every(day=>Number.isInteger(day)&&day>=0&&day<=6)
    && Array.isArray(row.done)&&row.done.every(date)&&Number.isInteger(row.count)&&row.count>=0
    && typeof row.numbered==='boolean'&&Number.isInteger(row.num_start)&&row.num_start>=1)) return false;
  if (!value.exams.every(row=>UUID.test(row.id)&&text(row.subject,40)&&['mid','final'].includes(row.kind)&&date(row.date)
    && Number.isInteger(row.rounds)&&row.rounds>=1&&row.rounds<=5&&[3,5,7,10,14].includes(row.lead)
    && row.done&&typeof row.done==='object'&&!Array.isArray(row.done))) return false;
  if (value.timetable && (!Array.isArray(value.timetable.classes)||value.timetable.classes.length>60
    || !date(value.timetable.from)||!date(value.timetable.through)||value.timetable.until&&!date(value.timetable.until)
    || !value.timetable.mode || !Object.keys(MODE_LABELS).every(key=>typeof value.timetable.mode[key]==='boolean')
    || !value.timetable.classes.every(row=>text(row.subject,40)&&Number.isInteger(row.day)&&row.day>=0&&row.day<=6
      && (row.start===''||/^\d{2}:\d{2}$/.test(row.start))&&(row.end===''||/^\d{2}:\d{2}$/.test(row.end))&&text(row.room,120)))) return false;
  return true;
}

// The reference planner's SVG sampling, expressed as DOM geometry rather than HTML.
export function memoryCurve(item,today) {
  const base=item.catchup?item.learned:item.base, past=[base,...item.reviews].map(value=>schedule.diffDays(base,value));
  const future=schedule.projected(item,today).map((row,index)=>schedule.diffDays(base,index===0&&row.date<today?today:row.date));
  const events=[...past,...future],todayT=schedule.diffDays(base,today);
  const lastGap=item.offsets.at(-1)-(item.offsets.at(-2)||0);
  const end=Math.max((events.at(-1)||0)+Math.max(4,Math.round(lastGap*.5)),todayT+2,6);
  const points=[];
  for(let i=0;i<events.length;i++){
    const a=events[i],b=events[i+1]??end,count=Math.max(6,Math.ceil((b-a)/end*360));
    for(let s=0;s<=count;s++){const t=a+(b-a)*s/count;points.push({t,r:Math.exp(-(t-a)/2.5**i),segment:i});}
  }
  const remembered=Math.min(1,Math.exp(-Math.max(0,todayT-past.at(-1))/2.5**(past.length-1)));
  if(todayT>=0)points.push({t:todayT,r:remembered,segment:past.length-1});
  points.sort((a,b)=>a.segment-b.segment||a.t-b.t);
  return {base,end,events,todayT,remembered,past:points.filter(p=>p.segment<past.length&&p.t<=todayT),
    future:points.filter(p=>p.segment>=past.length-1&&p.t>=Math.max(0,todayT)),
    baseline:Array.from({length:201},(_,i)=>({t:end*i/200,r:Math.exp(-end*i/200)}))};
}

